-- Sample data for the Employee Management System.
-- Run after schema.sql on an empty database.
-- Departments, Roles and EmployeeCodeSequences rows are created by schema.sql;
-- the sequence numbers are updated at the bottom of this file.
-- Aadhaar/PAN values are encrypted with the sample Encryption:Key from the README.
-- Demo logins: admin / Admin@123, manager / Manager@123, employee / Employee@123

SET NOCOUNT ON;
BEGIN TRANSACTION;

-- Employees
SET IDENTITY_INSERT [Employees] ON;
SET IDENTITY_INSERT [Employees] OFF;

-- EmployeePersonalDetails

-- Users
SET IDENTITY_INSERT [Users] ON;
SET IDENTITY_INSERT [Users] OFF;

-- EmployeeTransferHistory
SET IDENTITY_INSERT [EmployeeTransferHistory] ON;
SET IDENTITY_INSERT [EmployeeTransferHistory] OFF;

-- EmployeeCodeSequences
UPDATE [EmployeeCodeSequences] SET [LastNumber] = 6 WHERE [DepartmentId] = 1;
UPDATE [EmployeeCodeSequences] SET [LastNumber] = 5 WHERE [DepartmentId] = 2;
UPDATE [EmployeeCodeSequences] SET [LastNumber] = 4 WHERE [DepartmentId] = 3;
UPDATE [EmployeeCodeSequences] SET [LastNumber] = 7 WHERE [DepartmentId] = 4;
UPDATE [EmployeeCodeSequences] SET [LastNumber] = 4 WHERE [DepartmentId] = 5;

COMMIT TRANSACTION;
